/*
c = a ⋅ b
        where
        a: scalar
        b: scalar
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT c;

    heartlib(
        const double & a,
        const double & b)
    {

        // c = a ⋅ b
        c = a * b;
    }
};

