function output = heartlib(a, b)
% output = heartlib(a, b)
%
%    c = a ⋅ b
%            where
%            a: scalar
%            b: scalar
    assert(numel(a) == 1);
    assert(numel(b) == 1);

    % c = a ⋅ b

    c = a * b;
    output.c = c;
end

